 IF (SELECT COUNT(*) FROM tradeskill_recipe_entries r JOIN rrc090_recipes q ON q.id=r.recipe_id)<>476 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC090 target entry multiplicity mismatch'; END IF;
 IF (SELECT COUNT(*) FROM tradeskill_recipe)<>recipes_before+IF(already_present=0,61,0) OR (SELECT COUNT(*) FROM tradeskill_recipe_entries)<>entries_before+IF(already_present=0,476,0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC090 unexpected table row-count delta'; END IF;
 IF EXISTS(SELECT 1 FROM rrc090_parents e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND BINARY r.`name` <=> BINARY e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND BINARY r.`notes` <=> BINARY e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND BINARY r.`content_flags` <=> BINARY e.`content_flags` AND BINARY r.`content_flags_disabled` <=> BINARY e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC090 prototype drift'; END IF;
 IF EXISTS(SELECT 1 FROM rrc090_parent_entries e LEFT JOIN tradeskill_recipe_entries r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)) OR (SELECT COUNT(*) FROM tradeskill_recipe_entries r JOIN rrc090_parents p ON p.id=r.recipe_id)<>111 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC090 prototype entries drift'; END IF;
 IF EXISTS(SELECT 1 FROM rrc090_required_recipes e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND BINARY r.`name` <=> BINARY e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND BINARY r.`notes` <=> BINARY e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND BINARY r.`content_flags` <=> BINARY e.`content_flags` AND BINARY r.`content_flags_disabled` <=> BINARY e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC090 requires exact RRC072 Charta subset'; END IF;
 IF EXISTS(SELECT 1 FROM rrc090_required_entries e LEFT JOIN tradeskill_recipe_entries r ON r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer` WHERE r.id IS NULL) OR (SELECT COUNT(*) FROM tradeskill_recipe_entries r JOIN rrc090_required_recipes q ON q.id=r.recipe_id)<>68 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC090 RRC072 Charta entry postimage mismatch'; END IF;
 DROP TEMPORARY TABLE rrc090_required_recipes;
 DROP TEMPORARY TABLE rrc090_required_entries;
 DROP TEMPORARY TABLE rrc090_parents;
 DROP TEMPORARY TABLE rrc090_parent_entries;
 DROP TEMPORARY TABLE rrc090_entries;
 DROP TEMPORARY TABLE rrc090_recipes;
 DROP TEMPORARY TABLE rrc090_items;
 COMMIT;
 SET own_transaction=FALSE;
 SELECT 'RRC090' AS batch,already_present AS previous_recipe_count,recipes_before AS recipes_before,(SELECT COUNT(*) FROM tradeskill_recipe) AS recipes_after,entries_before AS entries_before,(SELECT COUNT(*) FROM tradeskill_recipe_entries) AS entries_after,@@in_transaction AS in_transaction;
END//
DELIMITER ;
